set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
APPLY=0
for arg in "$@"; do if [[ "$arg" == "--apply" ]]; then APPLY=1; fi; done
[[ $APPLY -eq 1 ]] || { echo "Dry-run policy: rerun with --apply after review${DRY_RUN_NOTE:-}."; exit 0; }
[[ $EUID -eq 0 ]] || { echo "Run as root with sudo." >&2; exit 2; }

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
SOURCE="$ROOT/HYDRA-UMC-DATALAKE"
TARGET=/opt/hydra-umc/datalake
DEPLOY_CONTRACT=1
source "$HERE/deploy_lib.sh"
deploy_begin HYDRA-UMC-DATALAKE "$TARGET"
SVC_USER="hydra-umc-datalake"

[[ -f "$SOURCE/hydra-umc.project.json" ]] || { echo "HYDRA-UMC-DATALAKE source is incomplete: $SOURCE" >&2; exit 2; }
[[ -f "$SOURCE/systemd/hydra-umc-datalake-downsample.service" ]] || { echo "HYDRA-UMC-DATALAKE has no unit hydra-umc-datalake-downsample.service: $SOURCE" >&2; exit 2; }
[[ -f "$SOURCE/systemd/hydra-umc-datalake-downsample.timer" ]] || { echo "HYDRA-UMC-DATALAKE has no unit hydra-umc-datalake-downsample.timer: $SOURCE" >&2; exit 2; }
[[ -f "$SOURCE/systemd/hydra-umc-datalake-retention.service" ]] || { echo "HYDRA-UMC-DATALAKE has no unit hydra-umc-datalake-retention.service: $SOURCE" >&2; exit 2; }
[[ -f "$SOURCE/systemd/hydra-umc-datalake-retention.timer" ]] || { echo "HYDRA-UMC-DATALAKE has no unit hydra-umc-datalake-retention.timer: $SOURCE" >&2; exit 2; }
[[ -f "$SOURCE/systemd/hydra-umc-datalake.service" ]] || { echo "HYDRA-UMC-DATALAKE has no unit hydra-umc-datalake.service: $SOURCE" >&2; exit 2; }
if ! id -u "$SVC_USER" >/dev/null 2>&1; then
  useradd --system --home "$TARGET" --no-create-home --shell /usr/sbin/nologin "$SVC_USER"
fi
install -d -o root -g root -m 0755 "$TARGET"
HOOK="$HERE/build_hooks/datalake.sh"
[[ -f "$HOOK" ]] || { echo "HYDRA-UMC-DATALAKE needs its build hook build_hooks/datalake.sh: $HOOK" >&2; exit 2; }
source "$HOOK"
if [[ -d "$SOURCE/src" ]]; then
  rm -rf "$TARGET/src"
  cp -a "$SOURCE/src" "$TARGET/"
  chown -R root:root "$TARGET/src"
  chmod -R go-w "$TARGET/src"
fi
install -d -o "$SVC_USER" -g "$SVC_USER" -m 0750 "$TARGET/data"
install -m 0644 "$SOURCE/systemd/hydra-umc-datalake-downsample.service" /etc/systemd/system/hydra-umc-datalake-downsample.service
install -m 0644 "$SOURCE/systemd/hydra-umc-datalake-downsample.timer" /etc/systemd/system/hydra-umc-datalake-downsample.timer
install -m 0644 "$SOURCE/systemd/hydra-umc-datalake-retention.service" /etc/systemd/system/hydra-umc-datalake-retention.service
install -m 0644 "$SOURCE/systemd/hydra-umc-datalake-retention.timer" /etc/systemd/system/hydra-umc-datalake-retention.timer
install -m 0644 "$SOURCE/systemd/hydra-umc-datalake.service" /etc/systemd/system/hydra-umc-datalake.service
install -m 0644 "$SOURCE/hydra-umc.project.json" "$TARGET/hydra-umc.project.json"
systemctl daemon-reload
deploy_finish HYDRA-UMC-DATALAKE "$TARGET"
echo "datalake installed. Enable manually after review: systemctl enable --now hydra-umc-datalake"
if declare -F hook_after_install >/dev/null; then hook_after_install; fi
source "$HERE/service_registry.sh"
announce_health HYDRA-UMC-DATALAKE
